const { Given, When, Then, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = process.cwd();
const HTML_PATH = path.join(PROJECT_ROOT, 'index.html');

// --- World: per-scenario DOM and app state ---

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.app = null;
    this.localStorage = null;
  }
}

setWorldConstructor(TodoWorld);

// --- Setup and teardown ---

Before(function () {
  // Shared localStorage across reloads within one scenario
  if (!this._sharedStorage) {
    this._sharedStorage = {};
  }

  this.window = new Window({
    url: 'http://localhost/',
    pretendToBeVisual: true,
  });
  this.document = this.window.document;

  // Inject shared localStorage into the window
  const storage = this._sharedStorage;
  this.window.localStorage = {
    getItem(key) { return key in storage ? storage[key] : null; },
    setItem(key, value) { storage[key] = String(value); },
    removeItem(key) { delete storage[key]; },
    clear() { Object.keys(storage).forEach(k => delete storage[k]); },
    get length() { return Object.keys(storage).length; },
    key(index) { return Object.keys(storage)[index] || null; },
  };
  this.localStorage = this.window.localStorage;

  // Make window properties accessible globally for app.js
  this.window.globalThis.window = this.window;
  this.window.globalThis.document = this.document;
  this.window.globalThis.localStorage = this.window.localStorage;
  this.window.globalThis.location = this.window.location;

  // Load the HTML if it exists
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    this.document.write(html);
    this.document.close();
  }
});

After(function () {
  if (this.window) {
    this.window.close();
  }
});

// --- Helpers ---

function getApp(world) {
  if (world.app) return world.app;
  // Look for the app on the window (TodoMVC convention)
  if (world.window && world.window.app) {
    world.app = world.window.app;
    return world.app;
  }
  // Try loading app.js if it exists
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (fs.existsSync(appPath)) {
    try {
      world.window.globalThis.document = world.document;
      world.window.globalThis.localStorage = world.localStorage;
      world.window.globalThis.window = world.window;
      require(appPath);
      world.app = world.window.app || world.window.TodoApp || null;
    } catch (e) {
      // App may not be loadable yet
    }
  }
  return world.app;
}

function getTodoList(world) {
  return world.document.querySelector('.todo-list');
}

function getTodos(world) {
  const list = getTodoList(world);
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

function findTodoByText(world, text) {
  return getTodos(world).find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === text;
  });
}

function clickTodoCheckbox(world, todoText) {
  const li = findTodoByText(world, todoText);
  if (li) {
    const checkbox = li.querySelector('.toggle');
    if (checkbox) checkbox.click();
  }
}

function getNewTodoInput(world) {
  return world.document.querySelector('.new-todo');
}

function typeAndSubmit(world, text) {
  const input = getNewTodoInput(world);
  if (!input) throw new Error('New todo input not found');
  input.value = text;
  input.dispatchEvent(new world.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
}

function typeInEditInput(world, text) {
  const editing = world.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = text;
  editInput.dispatchEvent(new world.window.Event('input', { bubbles: true }));
}

function pressKey(world, key) {
  const editing = world.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.dispatchEvent(new world.window.KeyboardEvent('keydown', { key, keyCode: key === 'Enter' ? 13 : key === 'Escape' ? 27 : 0, bubbles: true }));
}

function blurEditInput(world) {
  const editing = world.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.dispatchEvent(new world.window.Event('blur', { bubbles: true }));
}

function clearEditInput(world) {
  const editing = world.document.querySelector('.editing');
  if (!editing) throw new Error('No editing todo found');
  const editInput = editing.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  editInput.value = '';
  editInput.dispatchEvent(new world.window.Event('input', { bubbles: true }));
}

function reloadPage(world) {
  // Save current state to localStorage
  const list = getTodoList(world);
  if (list) {
    const todos = getTodos(world).map(li => ({
      id: parseInt(li.dataset.id || li.getAttribute('data-id') || '0'),
      title: (li.querySelector('label') || {}).textContent || '',
      completed: li.classList.contains('completed'),
    }));
    if (todos.length > 0 || world.localStorage.getItem('todos-todomvc')) {
      world.localStorage.setItem('todos-todomvc', JSON.stringify(todos));
    }
  }

  // Get current hash
  const currentHash = world.window.location.hash;

  // Create a new window to simulate reload
  const newWindow = new Window({
    url: `http://localhost/${currentHash}`,
    pretendToBeVisual: true,
  });
  const newDoc = newWindow.document;

  // Share localStorage
  const storage = world._sharedStorage;
  newWindow.localStorage = world.localStorage;

  // Make globals available
  newWindow.globalThis.window = newWindow;
  newWindow.globalThis.document = newDoc;
  newWindow.globalThis.localStorage = newWindow.localStorage;
  newWindow.globalThis.location = newWindow.location;

  // Load the HTML
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    newDoc.write(html);
    newDoc.close();
  }

  // Close old window and switch to new
  world.window.close();
  world.window = newWindow;
  world.document = newDoc;

  // Try to load the app in the new window
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (fs.existsSync(appPath)) {
    try {
      newWindow.globalThis.document = newDoc;
      newWindow.globalThis.localStorage = newWindow.localStorage;
      newWindow.globalThis.window = newWindow;
      require(appPath);
      world.app = newWindow.app || newWindow.TodoApp || null;
    } catch (e) {
      // App may not be loadable
    }
  }
}

function addTodoDirectly(world, title, completed = false) {
  // Directly manipulate DOM and storage for Given steps
  const list = getTodoList(world);
  if (!list) return;

  const id = Date.now() + Math.floor(Math.random() * 1000);
  const li = world.document.createElement('li');
  li.dataset.id = id;
  if (completed) li.classList.add('completed');

  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox" ${completed ? 'checked' : ''}>
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;
  list.appendChild(li);

  // Update localStorage
  const todos = getTodos(world).map(el => ({
    id: parseInt(el.dataset.id || '0'),
    title: (el.querySelector('label') || {}).textContent || '',
    completed: el.classList.contains('completed'),
  }));
  world.localStorage.setItem('todos-todomvc', JSON.stringify(todos));

  // Show main and footer
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = '';
  if (footer) footer.style.display = '';

  // Update counter
  updateCounter(world);
}

function updateCounter(world) {
  const todos = getTodos(world);
  const activeCount = todos.filter(li => !li.classList.contains('completed')).length;
  const countEl = world.document.querySelector('.todo-count');
  if (countEl) {
    countEl.innerHTML = `<strong>${activeCount}</strong> ${activeCount === 1 ? 'item' : 'items'} left`;
  }
}

function hideMainAndFooter(world) {
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = 'none';
  if (footer) footer.style.display = 'none';
}

function showMainAndFooter(world) {
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = '';
  if (footer) footer.style.display = '';
}

function updateToggleAll(world) {
  const todos = getTodos(world);
  const allCompleted = todos.length > 0 && todos.every(li => li.classList.contains('completed'));
  const toggleAll = world.document.querySelector('#toggle-all');
  if (toggleAll) toggleAll.checked = allCompleted;
}

function updateClearCompleted(world) {
  const todos = getTodos(world);
  const hasCompleted = todos.some(li => li.classList.contains('completed'));
  const btn = world.document.querySelector('.clear-completed');
  if (btn) btn.style.display = hasCompleted ? '' : 'none';
}

// --- Given steps ---

Given('the todo application is loaded', function () {
  // App loaded with no todos - main and footer hidden
  hideMainAndFooter(this);
});

Given('the todo application is loaded with no todos', function () {
  // App loaded with no todos - main and footer hidden
  hideMainAndFooter(this);
});

Given('the todo application with todos {string}', function (text) {
  addTodoDirectly(this, text, false);
});

Given('the todo application with todos {string} and {string}', function (text1, text2) {
  addTodoDirectly(this, text1, false);
  addTodoDirectly(this, text2, false);
});

Given('the todo application with completed todos {string}', function (text) {
  addTodoDirectly(this, text, true);
  updateClearCompleted(this);
});

Given('the todo application with completed todos {string} and active todos {string}', function (completedText, activeText) {
  addTodoDirectly(this, completedText, true);
  addTodoDirectly(this, activeText, false);
  updateClearCompleted(this);
});

Given('the todo application with completed todos {string} and {string}', function (text1, text2) {
  addTodoDirectly(this, text1, true);
  addTodoDirectly(this, text2, true);
  updateClearCompleted(this);
});

// --- When steps ---

When('the user types {string} in the new todo input and presses Enter', function (text) {
  typeAndSubmit(this, text);
});

When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (toggleAll) toggleAll.click();
});

When('the user marks the todo {string} as completed', function (text) {
  clickTodoCheckbox(this, text);
});

When('the user marks the todo {string} as active', function (text) {
  clickTodoCheckbox(this, text);
});

When('the user hovers over the todo {string}', function (text) {
  const li = findTodoByText(this, text);
  if (li) {
    li.classList.add('hover');
    li.dispatchEvent(new this.window.Event('mouseenter', { bubbles: true }));
  }
});

When('the user clicks the destroy button for todo {string}', function (text) {
  const li = findTodoByText(this, text);
  if (li) {
    const destroyBtn = li.querySelector('.destroy');
    if (destroyBtn) destroyBtn.click();
  }
});

When('the user clicks the checkbox for todo {string}', function (text) {
  clickTodoCheckbox(this, text);
});

When('the user double-clicks the label for todo {string}', function (text) {
  const li = findTodoByText(this, text);
  if (li) {
    const label = li.querySelector('label');
    if (label) {
      label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
    }
  }
});

When('the user types {string} in the edit input', function (text) {
  typeInEditInput(this, text);
});

When('the user presses Enter', function () {
  pressKey(this, 'Enter');
});

When('the user presses Escape', function () {
  pressKey(this, 'Escape');
});

When('the user blurs the edit input', function () {
  blurEditInput(this);
});

When('the user clears the edit input', function () {
  clearEditInput(this);
});

When('the user clicks the clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) btn.click();
});

When('the user navigates to {string}', function (hash) {
  this.window.location.hash = hash;
  // Trigger hashchange
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When('the user reloads the page', function () {
  reloadPage(this);
});

When('the user creates and deletes a todo {string}', function (text) {
  // Create the todo
  typeAndSubmit(this, text);
  // Then delete it
  const li = findTodoByText(this, text);
  if (li) {
    const destroyBtn = li.querySelector('.destroy');
    if (destroyBtn) destroyBtn.click();
  }
});

When('the user creates todos {string} and {string}', function (text1, text2) {
  typeAndSubmit(this, text1);
  typeAndSubmit(this, text2);
});

// --- Then steps ---

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  const isHidden = !main || main.style.display === 'none' || main.offsetParent === null;
  if (!isHidden) throw new Error('Main section is visible but should be hidden');
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  const isHidden = !footer || footer.style.display === 'none' || footer.offsetParent === null;
  if (!isHidden) throw new Error('Footer is visible but should be hidden');
});

Then('the new todo input is focused', function () {
  const input = getNewTodoInput(this);
  if (!input) throw new Error('New todo input not found');
  if (this.document.activeElement !== input) {
    throw new Error(`New todo input is not focused. Active element: ${this.document.activeElement ? this.document.activeElement.tagName : 'none'}`);
  }
});

Then('a todo with text {string} is visible in the list', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found in the list`);
});

Then('a todo with text {string} is not visible in the list', function (text) {
  const li = findTodoByText(this, text);
  if (li) throw new Error(`Todo with text "${text}" is visible but should not be`);
});

Then('the new todo input is cleared', function () {
  const input = getNewTodoInput(this);
  if (!input) throw new Error('New todo input not found');
  if (input.value !== '') {
    throw new Error(`New todo input value is "${input.value}" but should be empty`);
  }
});

Then('no todo items are visible in the list', function () {
  const todos = getTodos(this);
  if (todos.length > 0) {
    throw new Error(`${todos.length} todo items are visible but should be none`);
  }
});

Then('the todo list contains {int} items', function (count) {
  const todos = getTodos(this);
  if (todos.length !== count) {
    throw new Error(`Todo list contains ${todos.length} items but expected ${count}`);
  }
});

Then('the todo list contains {float} items', function (count) {
  const todos = getTodos(this);
  if (todos.length !== count) {
    throw new Error(`Todo list contains ${todos.length} items but expected ${count}`);
  }
});

Then('the todo {string} has the completed class', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Todo "${text}" does not have the completed class`);
  }
});

Then('all todos are marked as completed', function () {
  const todos = getTodos(this);
  for (const li of todos) {
    if (!li.classList.contains('completed')) {
      const text = (li.querySelector('label') || {}).textContent;
      throw new Error(`Todo "${text}" is not marked as completed`);
    }
  }
});

Then('all todos are marked as active', function () {
  const todos = getTodos(this);
  for (const li of todos) {
    if (li.classList.contains('completed')) {
      const text = (li.querySelector('label') || {}).textContent;
      throw new Error(`Todo "${text}" is still marked as completed`);
    }
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (!toggleAll.checked) {
    throw new Error('Toggle-all checkbox is not checked');
  }
});

Then('the toggle-all checkbox is unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (toggleAll.checked) {
    throw new Error('Toggle-all checkbox is still checked');
  }
});

Then('the clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('Clear completed button not found');
  if (btn.style.display === 'none') {
    throw new Error('Clear completed button is hidden but should be visible');
  }
});

Then('the clear completed button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  const isHidden = !btn || btn.style.display === 'none';
  if (!isHidden) {
    throw new Error('Clear completed button is visible but should be hidden');
  }
});

Then('the counter shows {string}', function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  if (!countEl) throw new Error('Counter not found');
  const actual = countEl.textContent.trim();
  if (actual !== expected) {
    throw new Error(`Counter shows "${actual}" but expected "${expected}"`);
  }
});

Then('the {string} filter link has the selected class', function (filterName) {
  const filters = this.document.querySelectorAll('.filters a');
  for (const a of filters) {
    if (a.textContent.trim() === filterName) {
      if (!a.classList.contains('selected')) {
        throw new Error(`Filter link "${filterName}" does not have the selected class`);
      }
      return;
    }
  }
  throw new Error(`Filter link "${filterName}" not found`);
});

Then('the todo {string} is in editing mode', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Todo "${text}" is not in editing mode`);
  }
});

Then('the todo {string} is not in editing mode', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found`);
  if (li.classList.contains('editing')) {
    throw new Error(`Todo "${text}" is still in editing mode`);
  }
});

Then('the edit input for todo {string} is focused', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found`);
  const editInput = li.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  if (this.document.activeElement !== editInput) {
    throw new Error(`Edit input for "${text}" is not focused`);
  }
});

Then('the destroy button for todo {string} is visible', function (text) {
  const li = findTodoByText(this, text);
  if (!li) throw new Error(`Todo with text "${text}" not found`);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
  const style = this.window.getComputedStyle(destroyBtn);
  if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
    throw new Error(`Destroy button for "${text}" is not visible`);
  }
});

