(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var editingId = null;
  var currentFilter = '/';

  // --- DOM references ---

  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  // --- Persistence ---

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function load() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      todos = data ? JSON.parse(data) : [];
    } catch (e) {
      todos = [];
    }
  }

  // --- ID generation ---

  function generateId() {
    return Date.now() + Math.floor(Math.random() * 1000);
  }

  // --- Rendering ---

  function render() {
    var filtered = todos.filter(function (todo) {
      if (currentFilter === '/active') return !todo.completed;
      if (currentFilter === '/completed') return todo.completed;
      return true;
    });

    // Clear the list
    todoList.innerHTML = '';

    // Render each todo
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');
      if (editingId === todo.id) li.classList.add('editing');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    updateCount();
    updateToggleAll();
    updateClearCompleted();
    updateMainAndFooter();
    updateFilterLinks();
  }

  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  function updateCount() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';
  }

  function updateToggleAll() {
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;
  }

  function updateClearCompleted() {
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function updateMainAndFooter() {
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateFilterLinks() {
    filterLinks.forEach(function (a) {
      var href = a.getAttribute('href');
      var filter = href.replace('#', '');
      if (filter === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  }

  // --- Actions ---

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: generateId(),
      title: title,
      completed: false,
    });
    save();
    render();
  }

  function toggleTodo(id) {
    todos = todos.map(function (t) {
      if (t.id === id) {
        return { id: t.id, title: t.title, completed: !t.completed };
      }
      return t;
    });
    save();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      destroyTodo(id);
      return;
    }
    todos = todos.map(function (t) {
      if (t.id === id) {
        return { id: t.id, title: newTitle, completed: t.completed };
      }
      return t;
    });
    editingId = null;
    save();
    render();
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    var newState = !allCompleted;
    todos = todos.map(function (t) {
      return { id: t.id, title: t.title, completed: newState };
    });
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function findTodoById(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return todos[i];
    }
    return null;
  }

  function findIdFromElement(el) {
    var li = el.closest('li');
    if (!li) return null;
    return parseInt(li.dataset.id, 10);
  }

  // --- Event handlers ---

  // New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Todo list events (delegated)
  todoList.addEventListener('click', function (e) {
    var target = e.target;

    // Toggle checkbox
    if (target.classList.contains('toggle')) {
      var id = findIdFromElement(target);
      if (id !== null) toggleTodo(id);
      return;
    }

    // Destroy button
    if (target.classList.contains('destroy')) {
      var id = findIdFromElement(target);
      if (id !== null) destroyTodo(id);
      return;
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var id = findIdFromElement(target);
      if (id !== null) {
        editingId = id;
        render();
        var li = todoList.querySelector('[data-id="' + id + '"]');
        if (li) {
          var editInput = li.querySelector('.edit');
          if (editInput) editInput.focus();
        }
      }
    }
  });

  // Edit input events
  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var id = findIdFromElement(target);
    if (id === null) return;

    if (e.keyCode === ENTER_KEY) {
      editTodo(id, target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      cancelEdit();
    }
  });

  todoList.addEventListener('blur', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var id = findIdFromElement(target);
    if (id === null) return;

    // Use setTimeout to avoid conflicts with click events
    setTimeout(function () {
      if (editingId === id) {
        editTodo(id, target.value);
      }
    }, 0);
  }, true);

  todoList.addEventListener('input', function (e) {
    // Keep edit input value in sync (for clear operations)
  });

  // Toggle all
  toggleAll.addEventListener('change', function () {
    toggleAllTodos();
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // Filter links
  filterLinks.forEach(function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      var href = a.getAttribute('href');
      currentFilter = href.replace('#', '');
      window.location.hash = href;
      render();
    });
  });

  // Hash change
  function handleHashChange() {
    var hash = window.location.hash || '#/';
    var filter = hash.replace('#', '');
    if (filter === '/' || filter === '/active' || filter === '/completed') {
      currentFilter = filter;
      render();
    }
  }

  window.addEventListener('hashchange', handleHashChange);

  // --- Initialize ---

  function init() {
    load();
    handleHashChange();
    render();
    newTodoInput.focus();
  }

  init();
})();

