function loadApp(world) {
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (!fs.existsSync(appPath)) return null;
  try {
    // Set globals before loading so the app's IIFE sees the right window/document
    world.window.globalThis.document = world.document;
    world.window.globalThis.localStorage = world.localStorage;
    world.window.globalThis.window = world.window;
    world.window.globalThis.location = world.window.location;
    // Clear require cache so each scenario gets a fresh app
    delete require.cache[require.resolve(appPath)];
    require(appPath);
    return true;
  } catch (e) {
    return null;
  }
}

