  var STORAGE_KEY = 'todos-todomvc';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var editingId = null;
  var currentFilter = '/';

  // --- DOM references (set after DOM is ready) ---

  var newTodoInput, todoList, toggleAll, mainSection, footer, todoCount, clearCompletedBtn, filterLinks;

