    if (!toggleAll) return;
    var allCompleted = todos.length > 0;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) { allCompleted = false; break; }
    }
    toggleAll.checked = allCompleted;
  }

  function updateClearCompleted() {
    if (!clearCompletedBtn) return;
    var hasCompleted = false;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].completed) { hasCompleted = true; break; }
    }
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function updateMainAndFooter() {
    if (!mainSection || !footer) return;
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateFilterLinks() {
    if (!filterLinks) return;
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      var href = a.getAttribute('href');
      var filter = href.replace('#', '');
      if (filter === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  // --- Actions ---

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: generateId(),
      title: title,
      completed: false,
    });
    save();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (!newTitle) {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = newTitle;
        break;
      }
    }
    editingId = null;
    save();
    render();
  }

  function startEdit(id) {
    editingId = id;
    render();
    // Focus the edit input
    var li = todoList.querySelector('[data-id="' + id + '"]');
    if (li) {
      var editInput = li.querySelector('.edit');
      if (editInput) editInput.focus();
    }
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  function toggleAllTodos() {
    var allCompleted = true;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) { allCompleted = false; break; }
    }
    var newState = !allCompleted;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = newState;
    }
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  // --- Event handlers ---

  function setupEvents() {
    // New todo input
    if (newTodoInput) {
      newTodoInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          addTodo(newTodoInput.value);
          newTodoInput.value = '';
        }
      });
    }

    // Todo list events (delegated)
    if (todoList) {
      todoList.addEventListener('click', function (e) {
        var target = e.target;

        // Toggle checkbox
        if (target.classList.contains('toggle')) {
          var id = findIdFromElement(target);
          if (id !== null) toggleTodo(id);
          return;
        }

        // Destroy button
        if (target.classList.contains('destroy')) {
          var id = findIdFromElement(target);
          if (id !== null) destroyTodo(id);
          return;
        }
      });

      // Double-click to edit
      todoList.addEventListener('dblclick', function (e) {
        var target = e.target;
        if (target.tagName === 'LABEL') {
          var id = findIdFromElement(target);
          if (id !== null) startEdit(id);
        }
      });

      // Edit input keydown
      todoList.addEventListener('keydown', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;

        var id = findIdFromElement(target);
        if (id === null) return;

        if (e.keyCode === ENTER_KEY) {
          e.preventDefault();
          editTodo(id, target.value);
        } else if (e.keyCode === ESCAPE_KEY) {
          e.preventDefault();
          cancelEdit();
        }
      });

      // Edit input blur
      todoList.addEventListener('focusout', function (e) {
        var target = e.target;
        if (!target.classList.contains('edit')) return;

        var id = findIdFromElement(target);
        if (id === null) return;

        // Use setTimeout to avoid conflicts with click events
        setTimeout(function () {
          // Only save if still editing this todo
          if (editingId === id) {
            editTodo(id, target.value);
          }
        }, 0);
      });
    }

    // Toggle all
    if (toggleAll) {
      toggleAll.addEventListener('change', function () {
        toggleAllTodos();
      });
    }

    // Clear completed
    if (clearCompletedBtn) {
      clearCompletedBtn.addEventListener('click', function () {
        clearCompleted();
      });
    }

    // Filter links
    if (filterLinks) {
      for (var i = 0; i < filterLinks.length; i++) {
        (function (a) {
          a.addEventListener('click', function (e) {
            e.preventDefault();
            var href = a.getAttribute('href');
            currentFilter = href.replace('#', '');
            window.location.hash = href;
            render();
          });
        })(filterLinks[i]);
      }
    }

    // Hash change
    window.addEventListener('hashchange', function () {
      var hash = window.location.hash || '#/';
      var filter = hash.replace('#', '');
      if (filter === '/' || filter === '/active' || filter === '/completed') {
        currentFilter = filter;
        render();
      }
    });
  }

  function findIdFromElement(el) {
    var li = el.closest('li');
    if (!li) return null;
    return parseInt(li.dataset.id, 10);
  }

  // --- Initialize ---

  function init() {
    cacheDom();
    load();
    // Set initial filter from hash
    var hash = window.location.hash || '#/';
    var filter = hash.replace('#', '');
    if (filter === '/' || filter === '/active' || filter === '/completed') {
      currentFilter = filter;
    }
    render();
    setupEvents();
    if (newTodoInput) newTodoInput.focus();
  }

  // --- Public API (for step definitions) ---

  window.app = {
    addTodo: addTodo,
    toggleTodo: toggleTodo,
    destroyTodo: destroyTodo,
    editTodo: editTodo,
    startEdit: startEdit,
    cancelEdit: cancelEdit,
    toggleAll: toggleAllTodos,
    clearCompleted: clearCompleted,
    setFilter: function (filter) {
      currentFilter = filter;
      window.location.hash = '#' + filter;
      render();
    },
    getTodos: function () { return todos.slice(); },
    render: render,
    init: init,
  };

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = process.cwd();
const HTML_PATH = path.join(PROJECT_ROOT, 'index.html');

// --- World: per-scenario DOM and app state ---

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this._sharedStorage = {};
  }
}

setWorldConstructor(TodoWorld);

// --- Setup and teardown ---

Before(function () {
  this.window = new Window({
    url: 'http://localhost/',
    pretendToBeVisual: true,
  });
  this.document = this.window.document;

  // Shared localStorage across reloads within one scenario
  const storage = this._sharedStorage;
  this.window.localStorage = {
    getItem(key) { return key in storage ? storage[key] : null; },
    setItem(key, value) { storage[key] = String(value); },
    removeItem(key) { delete storage[key]; },
    clear() { Object.keys(storage).forEach(k => delete storage[k]); },
    get length() { return Object.keys(storage).length; },
    key(index) { return Object.keys(storage)[index] || null; },
  };

  // Set globals for the app to pick up
  this.window.globalThis.window = this.window;
  this.window.globalThis.document = this.document;
  this.window.globalThis.localStorage = this.window.localStorage;
  this.window.globalThis.location = this.window.location;
  this.window.globalThis.DOMParser = this.window.DOMParser;

  // Load the HTML
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    this.document.write(html);
    this.document.close();
  }

  // Load the app (fresh per scenario via cache clear)
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (fs.existsSync(appPath)) {
    try {
      delete require.cache[require.resolve(appPath)];
      require(appPath);
    } catch (e) {
      // App may have load errors - will surface as test failures
    }
  }
});

After(function () {
  if (this.window) {
    this.window.close();
  }
});

// --- Helpers ---

function app(world) {
  return world.window.app;
}

function getTodoList(world) {
  return world.document.querySelector('.todo-list');
}

function getTodos(world) {
  const list = getTodoList(world);
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

function findTodoByText(world, text) {
  return getTodos(world).find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === text;
  });
}

function updateCounter(world) {
  const todos = getTodos(world);
  const activeCount = todos.filter(li => !li.classList.contains('completed')).length;
  const countEl = world.document.querySelector('.todo-count');
  if (countEl) {
    countEl.innerHTML = `<strong>${activeCount}</strong> ${activeCount === 1 ? 'item' : 'items'} left`;
  }
}

function hideMainAndFooter(world) {
  const main = world.document.querySelector('.main');
  const footer = world.document.querySelector('.footer');
  if (main) main.style.display = 'none';
  if (footer) footer.style.display = 'none';
}

function reloadPage(world) {
  // Save current state to localStorage
  const todos = getTodos(world).map(li => ({
    id: parseInt(li.dataset.id || '0'),
    title: (li.querySelector('label') || {}).textContent || '',
    completed: li.classList.contains('completed'),
  }));
  if (todos.length > 0 || world._sharedStorage['todos-todomvc']) {
    world._sharedStorage['todos-todomvc'] = JSON.stringify(todos);
  }

  // Get current hash
  const currentHash = world.window.location.hash;

  // Create a new window to simulate reload
  const newWindow = new Window({
    url: `http://localhost/${currentHash}`,
    pretendToBeVisual: true,
  });
  const newDoc = newWindow.document;

  // Share localStorage
  newWindow.localStorage = world.window.localStorage;

  // Make globals available
  newWindow.globalThis.window = newWindow;
  newWindow.globalThis.document = newDoc;
  newWindow.globalThis.localStorage = newWindow.localStorage;
  newWindow.globalThis.location = newWindow.location;
  newWindow.globalThis.DOMParser = newWindow.DOMParser;

  // Load the HTML
  if (fs.existsSync(HTML_PATH)) {
    const html = fs.readFileSync(HTML_PATH, 'utf8');
    newDoc.write(html);
    newDoc.close();
  }

  // Close old window and switch to new
  world.window.close();
  world.window = newWindow;
  world.document = newDoc;

  // Load the app
  const appPath = path.join(PROJECT_ROOT, 'js', 'app.js');
  if (fs.existsSync(appPath)) {
    try {
      delete require.cache[require.resolve(appPath)];
      require(appPath);
    } catch (e) {
      // App may not be loadable
    }
  }
}

