Given('the todo application with todos {string}', function (text) {
  const a = app(this);
  if (a) {
    a.addTodo(text);
  } else {
    // Fallback: direct DOM manipulation
    const list = getTodoList(this);
    if (list) {
      const id = Date.now() + Math.floor(Math.random() * 1000);
      const li = this.document.createElement('li');
      li.dataset.id = id;
      li.innerHTML = `<div class="view"><input class="toggle" type="checkbox"><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
      list.appendChild(li);
      updateCounter(this);
    }
  }
});

Given('the todo application with todos {string} and {string}', function (text1, text2) {
  const a = app(this);
  if (a) {
    a.addTodo(text1);
    a.addTodo(text2);
  } else {
    const list = getTodoList(this);
    if (list) {
      [text1, text2].forEach(text => {
        const id = Date.now() + Math.floor(Math.random() * 1000);
        const li = this.document.createElement('li');
        li.dataset.id = id;
        li.innerHTML = `<div class="view"><input class="toggle" type="checkbox"><label>${text}</label><button class="destroy"></button></div><input class="edit" value="${text}">`;
        list.appendChild(li);
      });
      updateCounter(this);
    }
